import { test, expect } from '@playwright/test';

test.describe('Upload Cancellation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should successfully cancel an in-progress upload', async ({ page }) => {
    // Verify upload button is visible
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Click upload button to start upload
    await uploadButton.click();

    // Verify upload progress bar appears
    const progressBar = page.locator('[data-testid="upload-progress-bar"]');
    await expect(progressBar).toBeVisible();

    // Verify upload cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Click cancel button
    await cancelButton.click();

    // Verify upload progress bar disappears
    await expect(progressBar).not.toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText(/upload cancelled/i);
    await expect(successMessage).toBeVisible();

    // Verify file name is cleared
    const fileInput = page.getByLabel(/file/i);
    await expect(fileInput).toHaveValue('');

    // Verify error message is not visible
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();
  });

  test('should display error when canceling a failed upload', async ({ page }) => {
    // Verify upload button is visible
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Click upload button to start upload
    await uploadButton.click();

    // Verify upload progress bar appears
    const progressBar = page.locator('[data-testid="upload-progress-bar"]');
    await expect(progressBar).toBeVisible();

    // Verify upload cancel button is visible
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await expect(cancelButton).toBeVisible();

    // Click cancel button
    await cancelButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/upload failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify upload progress bar still exists
    await expect(progressBar).toBeVisible();

    // Verify file name is still present
    const fileInput = page.getByLabel(/file/i);
    await expect(fileInput).toHaveValue('');

    // Verify success message is not visible
    const successMessage = page.getByText(/upload cancelled/i);
    await expect(successMessage).not.toBeVisible();
  });
});
